/* @lc app=leetcode id=3351 lang=kotlin */ class Solution { fun sumOfGoodSubsequences(nums: IntArray): Int = 1_000_000_007L.let { M -> HashMap<Int, Long>().let { cnt -> HashMap<Int, Long>().let { sm -> nums.forEach { v -> ((1 + (cnt[v - 1] ?: 0) + (cnt[v + 1] ?: 0)) % M).let { nc -> ((v * nc + (sm[v - 1] ?: 0) + (sm[v + 1] ?: 0)) % M).let { ns -> cnt.merge(v, nc) { a, b -> (a + b) % M }.also { sm.merge(v, ns) { a, b -> (a + b) % M } } } } }.let { (sm.values.sum() % M).toInt() } } } } }